//! Golden tests for `%if` and whole-file parsing: expected output from the
//! reference tmux 3.8, generated by `tests/cmd_if_cases.sh` into
//! `golden/if.txt` (its header says which reference commands ran).

use std::collections::BTreeMap;
use std::fmt::Write as _;

use super::{CommandList, ConfigEnv, Group, ParseOpts, PrintFlags, parse_file};
use crate::format::{FormatContext, expand_str};

const CASES: &str = include_str!("golden/if.txt");

/// `HOME` in the reference run (the script pins it).
const HOME: &str = "/home/vtmux-test";

/// The reference server's global environment as far as the cases read it.
/// Conditions see it through `format_find`'s environment fallback; no
/// option the cases test is set when they are expanded (`set` runs after
/// the whole file is parsed), and `#{vtmux_version}` is empty on tmux.
struct Env(BTreeMap<String, String>);

impl FormatContext for Env {
    fn get(&self, name: &str) -> Option<String> {
        self.0.get(name).cloned()
    }
}

impl ConfigEnv for Env {
    fn var(&self, name: &str) -> Option<String> {
        self.0.get(name).cloned()
    }
    fn home(&self, user: Option<&str>) -> Option<String> {
        user.is_none().then(|| HOME.to_owned())
    }
    fn set(&mut self, name: &str, value: &str, _hidden: bool) {
        self.0.insert(name.to_owned(), value.to_owned());
    }
    fn expand(&self, template: &str) -> String {
        expand_str(template, self)
    }
}

/// `source-file -nv F` (or, for `env-*`, `source-file F` then the `T_`
/// variables) as the script records it.
fn run(name: &str, text: &str) -> String {
    let mut env = Env(BTreeMap::from([("HOME".to_owned(), HOME.to_owned())]));
    let applying = name.starts_with("env-");
    let opts = ParseOpts {
        parse_only: !applying,
        one_group: false,
    };
    let mut out = String::new();
    let mut printed = |group: Group<'_>| {
        if !applying {
            let list = CommandList {
                calls: group.calls.to_vec(),
            };
            let text = list.print(PrintFlags::default());
            let _ = writeln!(out, "F:{}: {text}", group.line);
        }
    };
    let result = parse_file(text, &mut env, opts, Some(&mut printed));
    let code = match result {
        Ok(_) => 0,
        Err(e) => {
            let _ = writeln!(out, "F:{}: {}", e.line, e.error);
            1
        }
    };
    if applying {
        for (k, v) in env.0.iter().filter(|(k, _)| k.starts_with("T_")) {
            let _ = writeln!(out, "{k}={v}");
        }
    }
    let _ = writeln!(out, "exit={code}");
    out
}

/// `### name`, the file, `---`, the expected output, `%%`.
fn cases() -> Vec<(&'static str, String, String)> {
    let mut out = Vec::new();
    let mut lines = CASES.split('\n');
    while let Some(line) = lines.next() {
        let Some(name) = line.strip_prefix("### ") else {
            continue;
        };
        let text: Vec<&str> = lines.by_ref().take_while(|l| *l != "---").collect();
        let want: Vec<&str> = lines.by_ref().take_while(|l| *l != "%%").collect();
        // The script writes the file with a final newline.
        out.push((name, text.join("\n") + "\n", want.join("\n") + "\n"));
    }
    out
}

#[test]
fn if_cases_match_reference() {
    let cases = cases();
    assert!(cases.len() >= 60, "{} cases", cases.len());
    let failures: Vec<String> = cases
        .iter()
        .filter_map(|(name, text, want)| {
            let got = run(name, text);
            (got != *want).then(|| format!("### {name}\n{text}--- want\n{want}--- got\n{got}"))
        })
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
